fn hide_item_menu(app: &PealayerApp, response: egui::Response, label: String) -> bool {
    let mut hide = false;
    response.context_menu(|ui| {
        ui.label(egui::RichText::new(&label).strong());
        ui.separator();
        if ui
            .button(format!(
                "{} {} {label}",
                crate::ui::icons::EYE_SLASH,
                app.tr("Hide")
            ))
            .clicked()
        {
            hide = true;
            ui.close();
        }
    });
    hide
}

